import Foundation

/// Single source of truth for which Bible texts Bible+ may display, quote,
/// search, or hand to the AI companion.
///
/// Bible+ uses NO third-party Bible API at runtime. Every translation is
/// bundled in the app: KJV + WEB in `Shared/Content`, everything below in
/// `Resources/Bible/bible-<ID>.json` (generated by `scripts/bundle_bibles.py`).
///
/// Rule for adding a translation: it must be public domain, or its license
/// must allow BOTH commercial use (Bible+ is a paid app) AND derivatives (the
/// AI excerpts and paraphrases, Memorize alters text). Copyrighted versions
/// (NIV, ESV, NLT, NASB, NKJV, MSG, RVR1960, NVI, …), CC BY-NC and CC BY-ND
/// texts are not allowed. We also avoid Biblica-published "open" editions.
/// Licenses verified against eBible.org / helloao metadata on 2026-11-13.
enum TranslationLicensePolicy {

    struct Entry {
        let shortName: String
        let englishName: String
        let license: TranslationRef.License
        /// Where the license / source is documented (shown in attribution).
        let sourceURL: String
        var copyrightNotice: String? = nil
        var licenseURL: String? = nil
    }

    private static let publicDomain = TranslationRef.License(
        attribution: "not-required", commercialUse: "allowed", derivatives: "allowed", publicDomain: true, copyleft: false
    )
    private static let ccBySA = TranslationRef.License(
        attribution: "required", commercialUse: "allowed", derivatives: "allowed", publicDomain: false, copyleft: true
    )
    private static let ccBy = TranslationRef.License(
        attribution: "required", commercialUse: "allowed", derivatives: "allowed", publicDomain: false, copyleft: false
    )

    /// Every non-KJV/WEB translation bundled in the app.
    static let bundled: [String: Entry] = [
        // English (public domain)
        "BSB": Entry(shortName: "BSB", englishName: "Berean Standard Bible", license: publicDomain, sourceURL: "https://berean.bible/"),
        "eng_asv": Entry(shortName: "ASV", englishName: "American Standard Version (1901)", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=eng-asv"),
        "eng_ylt": Entry(shortName: "YLT", englishName: "Young's Literal Translation", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=engylt"),
        "eng_dra": Entry(shortName: "DRA", englishName: "Douay-Rheims 1899", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=engDRA"),
        // Other languages — public domain
        "spa_r09": Entry(shortName: "R09", englishName: "Reina Valera 1909", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=spaRV1909"),
        "fra_lsg": Entry(shortName: "LSG", englishName: "Louis Segond 1910", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=fraLSG"),
        "deu_l12": Entry(shortName: "L12", englishName: "Luther Bible 1912", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=deu1912"),
        "ita_riv": Entry(shortName: "RIV", englishName: "Riveduta 1927", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=ita1927"),
        "rus_syn": Entry(shortName: "SYN", englishName: "Russian Synodal Bible", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=russyn"),
        "cmn_cu1": Entry(shortName: "CU1", englishName: "Chinese Union Version (Simplified)", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=cmn-cu89s"),
        "cmn_cuv": Entry(shortName: "CUV", englishName: "Chinese Union Version (Traditional)", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=cmn-cu89t"),
        "kor_old": Entry(shortName: "KOR", englishName: "Korean Bible 1910", license: publicDomain, sourceURL: "https://ebible.org/details.php?id=kor"),
        "jpn_kou": Entry(shortName: "口語訳", englishName: "Japanese Kougo-yaku (1955)", license: publicDomain, sourceURL: "https://github.com/seven1m/open-bibles"),
        // Other languages — Creative Commons (attribution required)
        "por_blj": Entry(shortName: "BLJ", englishName: "Bíblia Livre", license: ccBy, sourceURL: "https://ebible.org/details.php?id=porbr2018", copyrightNotice: "© 2018 Diego Santos, Mario Sérgio, e Marco Teles", licenseURL: "https://creativecommons.org/licenses/by/4.0/"),
        "ind_tsi": Entry(shortName: "TSI", englishName: "Plain Indonesian Translation", license: ccBySA, sourceURL: "https://ebible.org/details.php?id=ind", copyrightNotice: "© 2021 Yayasan Alkitab Bahasa Kita (Albata) and Pioneer Bible Translators International; The Our Language Bible Organization", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/"),
        "tgl_ulb": Entry(shortName: "ULB", englishName: "Tagalog Unlocked Literal Bible", license: ccBySA, sourceURL: "https://ebible.org/details.php?id=tglulb", copyrightNotice: "© 2018 Door43 World Missions Community", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/"),
        "swh_ulb": Entry(shortName: "ULB", englishName: "Swahili Unlocked Literal Bible", license: ccBySA, sourceURL: "https://ebible.org/details.php?id=swhulb", copyrightNotice: "© 2019 Door43 World Missions Community", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/"),
    ]

    /// License terms by ID (used by `TranslationRef.isLicensedForCommercialUse`).
    static var knownLicenses: [String: TranslationRef.License] {
        bundled.mapValues(\.license)
    }

    /// IDs users may have stored from older builds that are NOT allowed.
    /// Anything not in `bundled` is denied anyway; listed for documentation.
    static let knownRestrictedRefIDs: Set<String> = [
        "ind_ayt",   // CC BY-NC (non-commercial)
        "pol_ubg",   // CC BY-ND (no derivatives)
        "amh_amh",   // no license information
        "pol_bib", "swh_bib", // Biblica open editions — avoided
    ]

    // MARK: - Queries

    /// Whether a translation ID may be loaded and shown.
    static func isAllowed(refID: String) -> Bool {
        if refID == TranslationRef.bundledKJV.id || refID == TranslationRef.bundledWEB.id { return true }
        return bundled[refID]?.license.permitsCommercialAppUse ?? false
    }

    /// Short badge name (e.g. "BSB", "R09").
    static func shortName(for refID: String) -> String? { bundled[refID]?.shortName }

    /// Human-readable name (e.g. "Reina Valera 1909").
    static func displayName(for refID: String) -> String? { bundled[refID]?.englishName }

    /// Attribution line required by the translation's license, or nil when
    /// none is required (public domain).
    static func attribution(for refID: String) -> String? {
        guard let entry = bundled[refID], entry.license.requiresAttribution else { return nil }
        let notice = entry.copyrightNotice ?? entry.englishName
        let licenseURL = entry.licenseURL ?? entry.sourceURL
        if entry.license.copyleft == true {
            return String(localized: "Scripture text: \(entry.englishName). \(notice). CC BY-SA 4.0: \(licenseURL). Source: \(entry.sourceURL). Formatting adapted for this app; verse wording unchanged. Adaptations of this text are shared under the same license.")
        }
        return String(localized: "Scripture text: \(entry.englishName). \(notice). CC BY 4.0: \(licenseURL). Source: \(entry.sourceURL). Formatting adapted for this app; verse wording unchanged.")
    }
}
